import requests, os, time

url = 'https://github.com/Hmbown/CodeWhale/releases/download/v0.8.44/codewhale-linux-x64'
proxies = {'http': 'http://127.0.0.1:7897', 'https': 'http://127.0.0.1:7897'}
out = '/tmp/codewhale-linux-x64'

# 检查已有文件大小
resume = 0
if os.path.exists(out):
    resume = os.path.getsize(out)
    print(f'Resuming from byte {resume}')

headers = {}
if resume:
    headers['Range'] = f'bytes={resume}-'

for attempt in range(3):
    try:
        print(f'Attempt {attempt+1}...')
        r = requests.get(url, proxies=proxies, headers=headers, stream=True, timeout=60)
        print(f'Status: {r.status_code}')
        if r.status_code in (200, 206):
            total = int(r.headers.get('content-length', 0)) + resume
            mode = 'ab' if resume else 'wb'
            downloaded = resume
            with open(out, mode) as f:
                for chunk in r.iter_content(8192):
                    f.write(chunk)
                    downloaded += len(chunk)
                    if total:
                        pct = downloaded * 100 // total
                        print(f'\r{pct}% ({downloaded}/{total})', end='')
            print(f'\nDone! {downloaded} bytes')
            break
        else:
            print(f'Failed: {r.status_code}')
    except Exception as e:
        print(f'Error: {e}')
        time.sleep(3)
