release = r.json()
for a in release['assets']:
    if a['name'] == 'codewhale-linux-x64':
        aid = a['id']
        print(f'Asset ID: {aid}, size: {a[\"size\"]}')

        # 通过 API 下载
        url = f'https://api.github.com/repos/Hmbown/CodeWhale/releases/assets/{aid}'
        dh = {'Accept': 'application/octet-stream'}
        r2 = requests.get(url, headers=dh, proxies=proxies, stream=True, timeout=120)
        print(f'Download status: {r2.status_code}')
        if r2.status_code == 200:
            total = int(r2.headers.get('content-length', 0))
            out = '/tmp/codewhale-linux-x64'
            dl = 0
            with open(out, 'wb') as f:
                for chunk in r2.iter_content(65536):
                    f.write(chunk)
                    dl += len(chunk)
                    if total: print(f'\r{dl*100//total}%', end='')
            print(f'\nDone! {dl} bytes')
